const science=C.pilots['science-wave'];science.families=['sc-period-count','sc-speed-from-wave','sc-wave-chart'];science.seeds=48;
science.generate=function(f,seed){let q;const cycles=2+seed%6,duration=10*(1+Math.floor(seed/6)%4),amplitude=1+Math.floor(seed/24);const base={unit:'science-wave',version:3,passage:'',options:null,tags:['science-wave'],grading:'number',mode:'solve',evidenceLevel:'application'};
if(f==='sc-period-count')q={...base,primarySkill:'science-wave:05',family:f,prompt:`${duration}msの間に${cycles}回振動した音の周波数は何Hz？`,answer:String(cycles*1000)+'/'+duration,answerUnit:'Hz',explanation:`${duration}ms=${duration/1000}秒。${cycles}÷${duration/1000}で周波数を求めます。`,hints:['まず時間を秒に直します。','振動回数を秒で割ります。']};
if(f==='sc-speed-from-wave'){const frequency=100+25*(seed%12),wavelength=1+Math.floor(seed/12);q={...base,primarySkill:'science-wave:06',family:f,mode:'connect',prompt:`周波数${frequency}Hz、波長${wavelength}mの波の速さは毎秒何m？`,answer:String(frequency*wavelength),answerUnit:'m/秒',explanation:`速さ＝周波数×波長なので${frequency}×${wavelength}=${frequency*wavelength}m/秒です。`,hints:['1秒当たりに何個の波長分が進むか考えよう。','周波数と波長を掛けます。']};}
if(f==='sc-wave-chart'){const c2=cycles+1;const higher=seed%2===0?'B':'A';q={...base,primarySkill:'science-wave:08',family:f,mode:'connect',grading:'choice',prompt:'同じ横軸・縦軸の尺度で記録したAとB。より高い音はどちら？',answer:higher,options:['A','B','同じ高さ'],graph:{durationMs:duration,traces:[{name:'A',cycles:higher==='A'?c2:cycles,amplitude},{name:'B',cycles:higher==='B'?c2:cycles,amplitude}]},explanation:`同じ${duration}msの間に振動回数が多い${higher}の方が周波数が高くなります。`,hints:['横軸の時間幅はAとBで同じです。','波の高さではなく、同じ時間内の繰り返し回数を比べよう。'],tags:['science-wave','graph']};}
if(!q)throw Error('Unknown science family');q.id='sc-g3:'+f+':'+seed;return q;};
